import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int numerator = sc.nextInt();
        int denominator = sc.nextInt();
        int limit = sc.nextInt();

        int gcd_value = gcd(numerator, denominator);
        numerator /= gcd_value;
        denominator /= gcd_value;

        long delta = 1L;
        double epsilon = 1e-10;

        long current_x = 0, best_x = 0;
        int best_y = 1;
        long current_y;

        for (current_y = 1; current_y <= limit; current_y++) {
            while (Math.abs(delta * numerator / (double)denominator - delta * current_x / (double)current_y)
                    > Math.abs(delta * numerator / (double)denominator - delta * (current_x + 10000) / (double)current_y)) {
                current_x += 10000;
            }
            while (Math.abs(delta * numerator / (double)denominator - delta * current_x / (double)current_y)
                    + epsilon > Math.abs(delta * numerator / (double)denominator - delta * (current_x + 1) / (double)current_y)) {
                current_x++;
            }
            double current_diff = Math.abs(delta * numerator / (double)denominator - delta * current_x / (double)current_y);
            double best_diff = Math.abs(delta * numerator / (double)denominator - delta * best_x / (double)best_y);
            if (current_diff < best_diff) {
                best_x = current_x;
                best_y = (int) current_y;
            }
        }

        long numerator_result = Math.max(0L, best_x - (denominator == 2 && best_x != numerator ? 1 : 0));
        System.out.println(numerator_result + "/" + best_y);
        sc.close();
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
